for(const [en,ko] of [["Close panel","패널 닫기"],["Back","뒤로"],["View Map","지도 보기"],["Select a monster","몬스터 선택"],["Select a type","타입 선택"],["No results","결과 없음"],["No results found","검색 결과가 없습니다"],["No matching monsters","조건에 맞는 몬스터가 없습니다"],["Search by location","출현 장소로 검색"],["Search by type","타입으로 검색"],["All monsters","모든 몬스터"],["All forms","모든 형태"],["Normal","일반"],["Rare","희귀"],["Rare Form","희귀 형태"],["Base Form","기본 형태"],["Health","체력"],["Physical Attack","물리 공격"],["Physical Defense","물리 방어"],["Special Attack","특수 공격"],["Special Defense","특수 방어"],["Total","합계"],["Base Stats:","기본 능력치:"],["Evolution Chain:","진화 계보:"],["Level:","레벨:"],["Level Up","레벨 상승"],["Evolves From","진화 전"],["Evolves Into","진화 후"],["Weakness","약점"],["Weaknesses","약점"],["Resistance","내성"],["Resistances","내성"],["Effective","효과 있음"],["Not Very Effective","효과가 별로 없음"],["No Effect","효과 없음"],["Attack Move Type","공격 기술 타입"],["Defend Mon Type","방어 몬스터 타입"],["Show All","모두 표시"],["Show More","더 보기"],["Show Less","접기"],["Caught Dokimon","포획한 도키몬"],["Caught Dokimon:","포획한 도키몬:"],["Rare forms caught","포획한 희귀 형태"],["Capture Progress","포획 진행률"],["Export CSV","CSV 내보내기"],["Import CSV","CSV 가져오기"],["Loading","불러오는 중"],["Error","오류"],["Retry","다시 시도"],["In Development","개발 중"],["Coming soon","곧 공개"],["Theme","테마"],["Search by name","이름으로 검색"],["Search monsters","몬스터 검색"],["Reset Filters","필터 초기화"],["Search...","검색..."],["No matches","일치하는 항목 없음"],["Results","결과"],["Result","결과"],["Show","표시"],["Hide","숨기기"],["View","보기"],["Details","상세 정보"],["Info","정보"],["Information","정보"],["Overview","개요"],["Collection","컬렉션"],["Help","도움말"],["About","소개"],["Tools","도구"],["Game","게임"],["Games","게임"],["Select","선택"],["Selected","선택됨"],["None selected","선택한 항목 없음"],["All selected","모두 선택됨"],["Unselect all","모두 선택 해제"],["Select all","모두 선택"],["Copy","복사"],["Copied!","복사됨!"],["Share","공유"],["Language","언어"],["Language:","언어:"],["Choose language","언어 선택"],["Save changes","변경 사항 저장"],["Changes saved","변경 사항이 저장되었습니다"],["Bound Form","속박 형태"],["Show Filters","필터 표시"],["No verified map coordinates available.","확인된 지도 좌표가 없습니다."],["Dokimon encounter locations","도키몬 출현 장소"],["Choose Dokimon","도키몬 선택"],["Choose a Dokimon","도키몬을 선택하세요"],["Scrollable encounter map","스크롤 가능한 출현 지도"],["Choose a Dokimon to view its encounter locations.","출현 장소를 보려면 도키몬을 선택하세요."],["Other reported locations (not mapped):","그 밖에 보고된 장소(지도에 표시되지 않음):"],["Other locations:","기타 출현 장소:"],["Selected:","선택:"],["mapped encounter locations","개의 출현 장소가 지도에 표시됨"],["mapped encounter location","개의 출현 장소가 지도에 표시됨"],["rare palettes","희귀 색상 변형"],["Select...","선택..."],["Classification:","분류:"],["Lore:","도감 설명:"],["Classification","분류"],["Lore","도감 설명"],["Moves learned","습득 기술"],["Move List + Lvls","기술 목록 및 습득 레벨"],["Unmapped locations exist for this Dokimon","이 도키몬에는 지도에 표시되지 않은 출현 장소가 있습니다"],["UNKNOWN","알 수 없음"],["ATK","공격"],["DEF","방어"],["M.ATK","특수 공격"],["M.DEF","특수 방어"],["SPD","스피드"],["Dex Number","도감 번호"],["Filter","필터"],["Filters","필터"],["Search Location","출현 장소 검색"],["Palettes:","색상 변형:"],["Caught?","포획 여부"],["No encounters found","출현 정보를 찾을 수 없습니다"],["Save","저장"],["Cancel","취소"]])koreanDict.set(en,ko);



