function translateJapaneseDynamic(value){
 let result=value;
 const patterns=[
  [/^(.*?) — (\d+) mapped encounter locations?$/,(_,name,count)=>(officialNameMap.get(name)||name)+' — '+count+'件の出現場所がマップに登録されています'],
  [/^Selected: (.*?) · Other locations: (.*)$/,(_,place,others)=>'選択中：'+place+' · その他の出現場所：'+others],
  [/^(.*?) rare palettes$/,(_,name)=>(officialNameMap.get(name)||name)+'のレアカラーパターン'],
  [/^(.*?) — (.*)$/,(_,name,place)=>officialNameMap.has(name)?officialNameMap.get(name)+' — '+place:null]
 ];
 for(const [pattern,replace] of patterns){const match=result.match(pattern);if(match){const translated=replace(...match);if(translated!==null)return translated}}
 return result;
}
function translateText(value,lang){
  if(!value||!value.trim())return value;
  const trim=value.trim();
  const source=lang==='ko'?koreanDict:lang==='es'?spanishDict:lang==='pt-BR'?portugueseDict:dict;
  if(source.has(trim))return value.replace(trim,source.get(trim));
  if(lang==='ja'){const dynamic=translateJapaneseDynamic(trim);if(dynamic!==trim)return value.replace(trim,dynamic);}
  if(lang==='ko'){
    const match=trim.match(/^(.*?) — (\d+) mapped encounter locations?$/);
    if(match)return value.replace(trim,(koreanNameMap.get(match[1])||match[1])+' — 지도에 표시된 출현 장소 '+match[2]+'개');
    const rare=trim.match(/^(.*?) rare palettes$/);
    if(rare)return value.replace(trim,(koreanNameMap.get(rare[1])||rare[1])+'의 희귀 색상 변형');
    const place=trim.match(/^(.*?) — (.*)$/);
    if(place&&koreanNameMap.has(place[1]))return value.replace(trim,koreanNameMap.get(place[1])+' — '+place[2]);
  }
  if(lang==='ja'||lang==='ko'||lang==='es'||lang==='pt-BR'){
    // Name-only labels can include a level, index or form suffix.
    const match=trim.match(/^(.+?)(\s*\((?:Lv\.?\s*\d+|Level\s*\d+)\))$/i);
    const nameMap=lang==='ko'?koreanNameMap:(lang==='es'||lang==='pt-BR')?spanishNameMap:officialNameMap;
    if(match&&nameMap.has(match[1]))return value.replace(trim,nameMap.get(match[1])+match[2]);
  }
  // Translate longer UI phrases while avoiding partial matches inside names.
  let translated=trim;
  for(const [en,ja] of [...source].filter(([key])=>key.length>8 && key.includes(' ')).sort((a,b)=>b[0].length-a[0].length)){
    if(translated.includes(en))translated=translated.split(en).join(ja);
  }
  return translated===trim?value:value.replace(trim,translated);
}

